using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class FloorWearSurvey {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/FloorSurfaceWear/";static string ScenePath(string floor)=>"Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+floor+"_Circular.unity";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");Directory.CreateDirectory(H);Directory.CreateDirectory(R+"/Docs/Review/2026-11-09_FloorSurfaceWear");string original=SceneManager.GetActiveScene().path;var summary=new List<object>();try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene(ScenePath(f));if(!File.Exists(H+f+"_before.unity"))EditorSceneManager.SaveScene(s,H+f+"_before.unity",true);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var records=new List<object>();foreach(var t in ts.Where(t=>t.gameObject.activeInHierarchy)){var rr=t.GetComponent<MeshRenderer>();var mf=t.GetComponent<MeshFilter>();if(!rr||!mf||!mf.sharedMesh)continue;var m=mf.sharedMesh;var ms=rr.sharedMaterials;var sub=new List<object>();for(int i=0;i<m.subMeshCount;i++){var ix=m.GetTriangles(i);var vs=m.vertices;double area=0,up=0;float lo=99999,hi=-99999;foreach(int j in ix){var q=t.TransformPoint(vs[j]);lo=Mathf.Min(lo,q.y);hi=Mathf.Max(hi,q.y);}for(int k=0;k<ix.Length;k+=3){var a=t.TransformPoint(vs[ix[k]]);var b=t.TransformPoint(vs[ix[k+1]]);var c=t.TransformPoint(vs[ix[k+2]]);var n=Vector3.Cross(b-a,c-a);area+=n.magnitude*.5;if(n.normalized.y>.85)up+=n.magnitude*.5;}var mat=i<ms.Length?ms[i]:null;sub.Add(new{slot=i,mat=mat?mat.name:"NULL",path=mat?AssetDatabase.GetAssetPath(mat):"",area,up,lo,hi});}records.Add(new{id=GlobalObjectId.GetGlobalObjectIdSlow(rr).ToString(),name=t.name,path=P(t),asset=AssetDatabase.GetAssetPath(m),p=V(t.position),e=V(t.eulerAngles),size=V(rr.bounds.size),mesh=m.name,uvCount=m.uv.Length,submeshes=sub});}
 File.WriteAllText(H+f+"_renderers.json",JsonConvert.SerializeObject(records,Formatting.Indented));var state=ts.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,p=V(t.position),e=V(t.eulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,center=V(c.bounds.center),size=V(c.bounds.size),enabled=c.enabled,trigger=c.isTrigger,mesh=c is MeshCollider mc&&mc.sharedMesh?AssetDatabase.GetAssetPath(mc.sharedMesh):""}),lights=t.GetComponents<Light>().Select(l=>new{l.intensity,l.range,l.spotAngle,color=new[]{l.color.r,l.color.g,l.color.b},l.enabled})});File.WriteAllText(H+f+"_state_before.json",JsonConvert.SerializeObject(state,Formatting.Indented));summary.Add(new{floor=f,renderers=records.Count,transforms=ts.Length});}}finally{EditorSceneManager.OpenScene(original);}return summary;}
}
